from pathlib import Path
from datetime import datetime
import py_compile
import re
import shutil
import sys

VERSION = "1.1.1"
ROOT = Path.cwd()
HTML = ROOT / "templates" / "index.html"
MODULO = ROOT / "factura_montos.py"
SERVIDOR = ROOT / "servidor.py"
MODULE_CONTENT = '"""Montos y datos resumidos de facturas F N°... para SincronizadorWeb.\n\nV1.1.1:\n- Extrae Neto / IVA / Total desde PDF con texto.\n- Extrae emisor y comuna cuando el formato lo permite.\n- Muestra un nombre corto para personas: primer nombre + primer apellido.\n- Conserva razón social completa para empresas.\n- Los cambios manuales de emisor/comuna persisten en .factura_montos.json.\n- No toca el flujo de sincronización de OT.\n"""\nimport json\nimport logging\nimport os\nimport re\nimport tempfile\nfrom datetime import datetime, timezone\nfrom threading import RLock\n\nfrom flask import jsonify, request\n\nLOG = logging.getLogger(__name__)\nMETADATA = \'.factura_montos.json\'\n_LOCK = RLock()\nFACTURA = re.compile(r\'^F\\s*N\\s*[°º]\\s*([0-9]+)(?![0-9])\', re.I)\nPDF = {\'.pdf\'}\nFOTOS = {\'.png\', \'.jpg\', \'.jpeg\', \'.webp\', \'.bmp\', \'.tiff\', \'.tif\', \'.heic\'}\nVALIDOS = PDF | FOTOS\nETIQUETAS = {\n    \'neto\': [r\'MONTO\\s+NETO\', r\'VALOR\\s+NETO\', r\'NETO\'],\n    \'iva\': [r\'I\\s*\\.?\\s*V\\s*\\.?\\s*A\\s*\\.?\\s*(?:\\(?19\\s*%\\)?)?\'],\n    \'total\': [r\'(?:MONTO\\s+)?TOTAL\\s+(?:A\\s+PAGAR)?\', r\'TOTAL\'],\n}\nIMPORTE = re.compile(r\'(?<![\\w\\d])\\$?\\s*(\\d{1,3}(?:[.,]\\d{3})+|\\d{1,10})(?!\\d)\')\n\n# Si aparece alguno de estos marcadores, no intentamos reducir la razón social\n# a "primer nombre + apellido".\nMARCADORES_EMPRESA = (\n    \' SPA\', \' S.P.A\', \' LTDA\', \' LIMITADA\', \' EIRL\', \' E.I.R.L\', \' S.A.\', \' S.A \',\n    \' SOCIEDAD \', \' EMPRESA \', \' COMERCIAL \', \' CONSTRUCTORA \', \' TRANSPORTES \',\n    \' SERVICIOS \', \' INGENIERIA \', \' INGENIERÍA \', \' DISTRIBUIDORA \',\n    \' COMERCIALIZADORA \', \' IMPORTADORA \', \' EXPORTADORA \', \' ASOCIACION \',\n    \' ASOCIACIÓN \', \' FUNDACION \', \' FUNDACIÓN \', \' COOPERATIVA \', \' CORPORACION \',\n    \' CORPORACIÓN \', \' MUNICIPALIDAD \', \' UNIVERSIDAD \', \' CLINICA \', \' CLÍNICA \',\n    \' RESTAURANT \', \' RESTAURANTE \', \' INVERSIONES \', \' AGRICOLA \', \' AGRÍCOLA \',\n)\nPARTICULAS_APELLIDO = {\'DE\', \'DEL\', \'LA\', \'LAS\', \'LOS\', \'VAN\', \'VON\', \'DA\', \'DAS\', \'DO\', \'DOS\'}\n\n\ndef es_factura(nombre):\n    if not isinstance(nombre, str):\n        return False\n    return bool(FACTURA.match(nombre)) and os.path.splitext(nombre)[1].lower() in VALIDOS\n\n\ndef numero_factura(nombre):\n    m = FACTURA.match(nombre)\n    return m.group(1) if m else None  # conserva ceros a la izquierda\n\n\ndef leer_pdf(ruta):\n    try:\n        import pymupdf\n    except ImportError as exc:\n        raise RuntimeError(\'Instala PyMuPDF: python -m pip install pymupdf\') from exc\n    doc = pymupdf.open(ruta)\n    try:\n        if doc.needs_pass:\n            raise ValueError(\'PDF protegido con contraseña\')\n        if len(doc) > 15:\n            raise ValueError(\'PDF demasiado largo para una factura\')\n        return \'\\n\'.join(pagina.get_text(sort=True) for pagina in doc)\n    finally:\n        doc.close()\n\n\ndef _lineas(texto):\n    return [re.sub(r\'\\s+\', \' \', l).strip() for l in (texto or \'\').splitlines() if l.strip()]\n\n\ndef _es_ruido_emisor(linea):\n    u = linea.upper()\n    ruido = (\n        \'FACTURA ELECTRONICA\', \'FACTURA ELECTRÓNICA\', \'BOLETA ELECTRONICA\',\n        \'R.U.T\', \'RUT:\', \'S.I.I\', \'SII -\', \'TELÉFONO\', \'TELEFONO\', \'EMAIL\',\n        \'E-MAIL\', \'WWW.\', \'HTTP\', \'GIRO:\', \'GIRO \', \'N°\', \'Nº\', \'NO.\',\n    )\n    return any(x in u for x in ruido)\n\n\ndef _candidato_nombre(linea):\n    if not linea or _es_ruido_emisor(linea):\n        return False\n    if len(linea) > 120:\n        return False\n    letras = re.findall(r\'[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+\', linea)\n    if len(letras) < 2:\n        return False\n    # Evita escoger direcciones obvias como nombre del emisor.\n    u = f\' {linea.upper()} \'\n    if any(x in u for x in (\' DIRECCION \', \' DIRECCIÓN \', \' CALLE \', \' AV. \', \' AVENIDA \', \' PJE. \', \' PASAJE \', \' CAMINO \', \' RUTA \')):\n        return False\n    return True\n\n\ndef abreviar_emisor(emisor):\n    """Para personas: primer nombre + primer apellido. Empresas: razón social completa."""\n    if not isinstance(emisor, str):\n        return None\n    limpio = re.sub(r\'\\s+\', \' \', emisor).strip(\' ,;:-\')\n    if not limpio:\n        return None\n    u = f\' {limpio.upper()} \'\n    if any(m in u for m in MARCADORES_EMPRESA):\n        return limpio\n    tokens = limpio.split()\n    if len(tokens) <= 2:\n        return limpio\n\n    def sacar_apellido(restantes):\n        if not restantes:\n            return []\n        grupo = [restantes.pop()]\n        while restantes and restantes[-1].upper().strip(\'.,\') in PARTICULAS_APELLIDO:\n            grupo.insert(0, restantes.pop())\n        return grupo\n\n    restantes = tokens[:]\n    _segundo = sacar_apellido(restantes)\n    primero = sacar_apellido(restantes)\n    if not primero or not restantes:\n        return limpio\n    return f"{restantes[0]} {\' \'.join(primero)}"\n\n\ndef extraer_identidad(texto):\n    """Extrae emisor y comuna desde la cabecera del DTE, sin leer el receptor."""\n    lineas = _lineas(texto)\n    if not lineas:\n        return {\'emisor_original\': None, \'emisor_corto\': None, \'comuna\': None}\n\n    corte = len(lineas)\n    receptor = re.compile(r\'\\bSE[NÑ]OR(?:\\(ES\\)|ES)?\\s*:|\\bRECEPTOR\\b|\\bRAZ[ÓO]N\\s+SOCIAL\\s+RECEPTOR\\b\', re.I)\n    for i, linea in enumerate(lineas):\n        if receptor.search(linea):\n            corte = i\n            break\n    cabecera = lineas[:corte]\n\n    emisor = None\n    # Patrón común SII: nombre inmediatamente antes de "Giro: ...".\n    for i, linea in enumerate(cabecera):\n        if re.search(r\'\\bGIRO\\s*:\', linea, re.I):\n            for j in range(i - 1, max(-1, i - 7), -1):\n                if _candidato_nombre(cabecera[j]):\n                    emisor = cabecera[j]\n                    break\n            if emisor:\n                break\n    if not emisor:\n        for linea in cabecera[:15]:\n            if _candidato_nombre(linea):\n                emisor = linea\n                break\n\n    comuna = None\n    # Primero privilegiamos una etiqueta explícita dentro de la cabecera del emisor.\n    for linea in cabecera:\n        m = re.search(r\'\\bCOMUNA\\s*:?\\s*([A-ZÁÉÍÓÚÜÑ][A-ZÁÉÍÓÚÜÑ .\\\'-]{1,45})$\', linea, re.I)\n        if m:\n            comuna = m.group(1).strip(\' .,-\')\n            break\n    if not comuna:\n        for linea in cabecera:\n            m = re.search(r\'\\bCIUDAD\\s*:?\\s*([A-ZÁÉÍÓÚÜÑ][A-ZÁÉÍÓÚÜÑ .\\\'-]{1,45})$\', linea, re.I)\n            if m:\n                comuna = m.group(1).strip(\' .,-\')\n                break\n\n    # Respaldo prudente para encabezados que integran la comuna al final de la dirección,\n    # por ejemplo "PJE. ... 3275 ... - TEMUCO".\n    if not comuna:\n        marcador_direccion = re.compile(r\'\\b(?:CALLE|AV\\.?|AVENIDA|PJE\\.?|PASAJE|CAMINO|RUTA)\\b\', re.I)\n        for linea in cabecera:\n            if not marcador_direccion.search(linea):\n                continue\n            m = re.search(r\'(?:\\s*[-–]\\s*|,\\s*)([A-ZÁÉÍÓÚÜÑ][A-ZÁÉÍÓÚÜÑ ]{2,35})$\', linea, re.I)\n            if m:\n                comuna = re.sub(r\'\\s+\', \' \', m.group(1)).strip()\n                break\n\n    return {\n        \'emisor_original\': emisor,\n        \'emisor_corto\': abreviar_emisor(emisor) if emisor else None,\n        \'comuna\': comuna,\n    }\n\n\ndef numero_clp(texto):\n    texto = texto.strip().replace(\' \', \'\')\n    if \'.\' in texto and \',\' in texto:\n        return None\n    if re.fullmatch(r\'\\d{1,3}(?:[.,]\\d{3})+\', texto):\n        return int(re.sub(r\'[.,]\', \'\', texto))\n    if re.fullmatch(r\'\\d{1,10}\', texto):\n        return int(texto)\n    return None\n\n\ndef importes_despues_etiqueta(linea, tipo):\n    for etiqueta in ETIQUETAS[tipo]:\n        for match in re.finditer(r\'(?<![A-Z])\' + etiqueta + r\'(?![A-Z])\', linea, flags=re.I):\n            resto = linea[match.end():]\n            resto = re.split(r\'(?<![A-Z])(?:MONTO\\s+NETO|VALOR\\s+NETO|NETO|I\\s*\\.?V\\s*\\.?A|TOTAL)(?![A-Z])\', resto, maxsplit=1, flags=re.I)[0]\n            hallados = [(numero_clp(m.group(1)), m.start()) for m in IMPORTE.finditer(resto[:55])]\n            hallados = [(n, p) for n, p in hallados if n is not None]\n            if hallados:\n                valores = {n for n, _ in hallados}\n                if len(valores) == 1:\n                    yield hallados[0][0]\n\n\ndef extraer_importes(texto):\n    if not texto or not texto.strip():\n        return None, \'PDF sin texto seleccionable (escaneado); ingresa los datos manualmente.\'\n    lineas = _lineas(texto)\n    encontrados = {tipo: set() for tipo in ETIQUETAS}\n    for tipo in ETIQUETAS:\n        for i, linea in enumerate(lineas):\n            for numero in importes_despues_etiqueta(linea, tipo):\n                encontrados[tipo].add(numero)\n            if re.fullmatch(r\'(?:\' + \'|\'.join(ETIQUETAS[tipo]) + r\')\\s*[:$\\s]*\', linea, flags=re.I) and i + 1 < len(lineas):\n                siguiente = re.fullmatch(r\'\\$?\\s*(\\d{1,3}(?:[.,]\\d{3})+|\\d{1,10})\', lineas[i + 1])\n                if siguiente:\n                    n = numero_clp(siguiente.group(1))\n                    if n is not None:\n                        encontrados[tipo].add(n)\n    if any(len(v) != 1 for v in encontrados.values()):\n        return None, \'No se pudieron identificar tres montos únicos; revisar manualmente.\'\n    montos = {tipo: next(iter(valores)) for tipo, valores in encontrados.items()}\n    if abs(montos[\'neto\'] + montos[\'iva\'] - montos[\'total\']) > 2:\n        return None, \'Neto + IVA no coincide con total; revisar posibles impuestos adicionales.\'\n    return montos, None\n\n\ndef _archivo_metadata(carpeta):\n    return os.path.join(carpeta, METADATA)\n\n\ndef _leer_metadata(carpeta):\n    try:\n        with open(_archivo_metadata(carpeta), encoding=\'utf-8\') as entrada:\n            contenido = json.load(entrada)\n        if isinstance(contenido.get(\'documentos\'), dict):\n            contenido[\'version\'] = 2\n            return contenido\n    except (FileNotFoundError, ValueError, OSError, TypeError, AttributeError):\n        pass\n    return {\'version\': 2, \'documentos\': {}}\n\n\ndef _guardar_metadata(carpeta, contenido):\n    contenido[\'version\'] = 2\n    descriptor, tmp = tempfile.mkstemp(prefix=\'.montos-\', suffix=\'.tmp\', dir=carpeta)\n    try:\n        with os.fdopen(descriptor, \'w\', encoding=\'utf-8\') as salida:\n            json.dump(contenido, salida, ensure_ascii=False, indent=2)\n        os.replace(tmp, _archivo_metadata(carpeta))\n    finally:\n        if os.path.exists(tmp):\n            os.unlink(tmp)\n\n\ndef _huella(ruta):\n    stat = os.stat(ruta)\n    return {\'tamano\': stat.st_size, \'mtime_ns\': stat.st_mtime_ns}\n\n\ndef _extraer_uno(ruta):\n    nombre = os.path.basename(ruta)\n    base = {\n        \'archivo\': nombre,\n        \'numero\': numero_factura(nombre),\n        \'huella\': _huella(ruta),\n        \'actualizado\': datetime.now(timezone.utc).isoformat(),\n        \'manual_campos\': {},\n    }\n    if os.path.splitext(nombre)[1].lower() not in PDF:\n        return {**base, \'estado\': \'manual_pendiente\', \'motivo\': \'Imagen: ingresa los datos manualmente.\', \'montos\': None,\n                \'datos_extraidos\': {\'emisor_original\': None, \'emisor_corto\': None, \'comuna\': None}}\n    try:\n        texto = leer_pdf(ruta)\n        identidad = extraer_identidad(texto)\n        montos, motivo = extraer_importes(texto)\n        return {**base, \'estado\': \'extraido\' if montos else \'manual_pendiente\', \'motivo\': motivo, \'montos\': montos,\n                \'datos_extraidos\': identidad}\n    except Exception as exc:\n        LOG.warning(\'No se pudo leer la factura PDF %s: %s\', nombre, exc)\n        return {**base, \'estado\': \'manual_pendiente\', \'motivo\': str(exc), \'montos\': None,\n                \'datos_extraidos\': {\'emisor_original\': None, \'emisor_corto\': None, \'comuna\': None}}\n\n\ndef _fusionar_manual(anterior, nuevo):\n    if not isinstance(anterior, dict):\n        return nuevo\n    manual_campos = anterior.get(\'manual_campos\') if isinstance(anterior.get(\'manual_campos\'), dict) else {}\n    nuevo[\'manual_campos\'] = dict(manual_campos)\n    # Compatibilidad V1.1: si los importes fueron digitados manualmente, se conservan\n    # incluso al reanalizar el PDF.\n    if anterior.get(\'estado\') == \'manual\' and isinstance(anterior.get(\'montos\'), dict):\n        nuevo[\'montos\'] = dict(anterior[\'montos\'])\n        nuevo[\'estado\'] = \'manual\'\n        if abs(nuevo[\'montos\'][\'neto\'] + nuevo[\'montos\'][\'iva\'] - nuevo[\'montos\'][\'total\']) > 2:\n            nuevo[\'motivo\'] = \'Revisado manualmente: el total difiere de neto + IVA (pueden existir impuestos adicionales).\'\n        else:\n            nuevo[\'motivo\'] = None\n    return nuevo\n\n\ndef _listado(carpeta):\n    return sorted([n for n in os.listdir(carpeta) if es_factura(n) and os.path.isfile(os.path.join(carpeta, n))], key=str.casefold)\n\n\ndef actualizar_carpeta(carpeta, forzar=False):\n    """Reanaliza lo necesario y conserva overrides manuales."""\n    with _LOCK:\n        datos = _leer_metadata(carpeta)\n        archivos = _listado(carpeta)\n        agrupados = {}\n        for nombre in archivos:\n            agrupados.setdefault(numero_factura(nombre), []).append(nombre)\n        documentos = datos[\'documentos\']\n        cambios = False\n        for nombre in archivos:\n            ruta = os.path.join(carpeta, nombre)\n            huella = _huella(ruta)\n            anterior = documentos.get(nombre)\n            tiene_identidad_v2 = isinstance((anterior or {}).get(\'datos_extraidos\'), dict)\n            if anterior and anterior.get(\'huella\') == huella and not forzar and tiene_identidad_v2:\n                continue\n            nuevo = _fusionar_manual(anterior, _extraer_uno(ruta))\n            documentos[nombre] = nuevo\n            cambios = True\n        if cambios:\n            _guardar_metadata(carpeta, datos)\n        salida = []\n        for numero, nombres in agrupados.items():\n            duplicados = len(nombres) > 1\n            for nombre in nombres:\n                registro = dict(documentos[nombre])\n                if duplicados:\n                    registro[\'estado\'] = \'duplicado\'\n                    registro[\'motivo\'] = \'Mismo número de factura en más de un archivo. Revisar antes de sumar.\'\n                salida.append(_presentar(registro))\n        return salida\n\n\ndef _presentar(registro):\n    auto = registro.get(\'datos_extraidos\') if isinstance(registro.get(\'datos_extraidos\'), dict) else {}\n    manual = registro.get(\'manual_campos\') if isinstance(registro.get(\'manual_campos\'), dict) else {}\n    salida = dict(registro)\n    salida[\'emisor_original\'] = auto.get(\'emisor_original\')\n    salida[\'emisor_auto\'] = auto.get(\'emisor_corto\')\n    salida[\'comuna_auto\'] = auto.get(\'comuna\')\n    salida[\'emisor\'] = manual.get(\'emisor_corto\') or auto.get(\'emisor_corto\')\n    salida[\'comuna\'] = manual.get(\'comuna\') or auto.get(\'comuna\')\n    salida[\'emisor_manual\'] = bool(manual.get(\'emisor_corto\'))\n    salida[\'comuna_manual\'] = bool(manual.get(\'comuna\'))\n    return salida\n\n\ndef actualizar_archivo_cargado(carpeta, ruta):\n    if es_factura(os.path.basename(ruta)):\n        with _LOCK:\n            datos = _leer_metadata(carpeta)\n            datos[\'documentos\'][os.path.basename(ruta)] = _extraer_uno(ruta)\n            _guardar_metadata(carpeta, datos)\n\n\ndef resumen(carpeta):\n    registros = actualizar_carpeta(carpeta)\n    suma = {\'neto\': 0, \'iva\': 0, \'total\': 0}\n    pendientes = 0\n    for registro in registros:\n        if registro[\'estado\'] not in {\'extraido\', \'manual\'} or not registro.get(\'montos\'):\n            pendientes += 1\n            continue\n        for clave in suma:\n            suma[clave] += registro[\'montos\'][clave]\n    return {\'documentos\': registros, \'sumas\': suma, \'pendientes\': pendientes}\n\n\ndef _texto_manual(valor, maximo=100):\n    if valor is None:\n        return None\n    if not isinstance(valor, str):\n        raise ValueError(\'Campo manual inválido\')\n    valor = re.sub(r\'\\s+\', \' \', valor).strip()\n    if len(valor) > maximo:\n        raise ValueError(\'Campo manual demasiado largo\')\n    return valor or None\n\n\ndef registrar_rutas_montos(app, base_facturas, validar_factura, ruta_aprobada):\n    def carpeta_valida(valor):\n        aprobada = validar_factura(valor)\n        if not aprobada or not os.path.isdir(aprobada):\n            return None\n        return aprobada\n\n    @app.get(\'/api/montos\')\n    def api_montos():\n        semana = request.args.get(\'semana\', \'\')\n        if not isinstance(semana, str) or not semana or semana in {\'.\', \'..\'} or \'/\' in semana or \'\\\\\' in semana:\n            return jsonify(error=\'Semana no válida\'), 400\n        ruta_semana = ruta_aprobada(base_facturas, semana)\n        if not ruta_semana or not os.path.isdir(ruta_semana):\n            return jsonify(error=\'Semana no encontrada\'), 404\n        try:\n            filas = []\n            suma = {\'neto\': 0, \'iva\': 0, \'total\': 0}\n            pendientes = 0\n            for nombre in sorted(os.listdir(ruta_semana), key=str.casefold):\n                carpeta = ruta_aprobada(ruta_semana, nombre)\n                if not carpeta or not os.path.isdir(carpeta) or os.path.islink(carpeta):\n                    continue\n                if os.path.exists(os.path.join(carpeta, \'ignorado.txt\')):\n                    continue\n                resultado = resumen(carpeta)\n                ot = \'\'\n                try:\n                    with open(os.path.join(carpeta, \'OT.txt\'), encoding=\'utf-8\') as entrada:\n                        ot = entrada.read().strip()\n                except OSError:\n                    pass\n                for doc in resultado[\'documentos\']:\n                    filas.append({**doc, \'carpeta\': nombre, \'ruta\': carpeta, \'ot\': ot})\n                for tipo in suma:\n                    suma[tipo] += resultado[\'sumas\'][tipo]\n                pendientes += resultado[\'pendientes\']\n            return jsonify(filas=filas, sumas=suma, pendientes=pendientes)\n        except OSError:\n            LOG.exception(\'Error leyendo resumen de montos\')\n            return jsonify(error=\'No se pudo acceder a los archivos de esta semana.\'), 500\n\n    @app.post(\'/api/montos/actualizar\')\n    def api_montos_actualizar():\n        data = request.get_json(silent=True) or {}\n        carpeta = carpeta_valida(data.get(\'ruta\'))\n        if not carpeta:\n            return jsonify(error=\'Carpeta de factura inválida\'), 400\n        try:\n            return jsonify(resultado=resumen_forzado(carpeta))\n        except OSError:\n            LOG.exception(\'Error actualizando montos\')\n            return jsonify(error=\'No se pudieron actualizar los montos.\'), 500\n\n    @app.post(\'/api/montos/actualizar_semana\')\n    def api_montos_actualizar_semana():\n        data = request.get_json(silent=True) or {}\n        semana = data.get(\'semana\', \'\')\n        if not isinstance(semana, str) or not semana or semana in {\'.\', \'..\'} or \'/\' in semana or \'\\\\\' in semana:\n            return jsonify(error=\'Semana inválida\'), 400\n        ruta_semana = ruta_aprobada(base_facturas, semana)\n        if not ruta_semana or not os.path.isdir(ruta_semana):\n            return jsonify(error=\'Semana no encontrada\'), 404\n        try:\n            actualizadas = 0\n            for nombre in os.listdir(ruta_semana):\n                carpeta = ruta_aprobada(ruta_semana, nombre)\n                if not carpeta or not os.path.isdir(carpeta) or os.path.islink(carpeta):\n                    continue\n                if os.path.isfile(os.path.join(carpeta, \'ignorado.txt\')):\n                    continue\n                actualizar_carpeta(carpeta, forzar=True)\n                actualizadas += 1\n            return jsonify(status=\'ok\', carpetas=actualizadas)\n        except OSError:\n            LOG.exception(\'Error actualizando montos de semana\')\n            return jsonify(error=\'No se pudo completar la actualización.\'), 500\n\n    @app.post(\'/api/montos/manual\')\n    def api_montos_manual():\n        data = request.get_json(silent=True) or {}\n        carpeta = carpeta_valida(data.get(\'ruta\'))\n        archivo = data.get(\'archivo\')\n        if not carpeta or not isinstance(archivo, str) or os.path.basename(archivo) != archivo or not es_factura(archivo):\n            return jsonify(error=\'Archivo o carpeta inválidos\'), 400\n        destino = ruta_aprobada(carpeta, archivo)\n        if not destino or not os.path.isfile(destino):\n            return jsonify(error=\'La factura no existe\'), 404\n        tiene_emisor = \'emisor\' in data\n        tiene_comuna = \'comuna\' in data\n        try:\n            emisor_corto = _texto_manual(data.get(\'emisor\'), 120) if tiene_emisor else None\n            comuna = _texto_manual(data.get(\'comuna\'), 80) if tiene_comuna else None\n        except ValueError as exc:\n            return jsonify(error=str(exc)), 400\n\n        montos = data.get(\'montos\')\n        if montos is not None:\n            if not isinstance(montos, dict) or any(type(montos.get(k)) is not int or montos[k] < 0 or montos[k] > 10**12 for k in (\'neto\', \'iva\', \'total\')):\n                return jsonify(error=\'Los importes deben ser enteros positivos en CLP\'), 400\n\n        with _LOCK:\n            datos = _leer_metadata(carpeta)\n            registro = datos[\'documentos\'].get(archivo)\n            if not isinstance(registro, dict) or registro.get(\'huella\') != _huella(destino):\n                registro = _extraer_uno(destino)\n            auto = registro.get(\'datos_extraidos\') if isinstance(registro.get(\'datos_extraidos\'), dict) else {}\n            manual = registro.get(\'manual_campos\') if isinstance(registro.get(\'manual_campos\'), dict) else {}\n\n            # Si el cliente envía el campo, lo actualizamos. Clientes V1.1 que sólo\n            # envían montos no borran correcciones de emisor/comuna.\n            if tiene_emisor:\n                if emisor_corto and emisor_corto != auto.get(\'emisor_corto\'):\n                    manual[\'emisor_corto\'] = emisor_corto\n                else:\n                    manual.pop(\'emisor_corto\', None)\n            if tiene_comuna:\n                if comuna and comuna != auto.get(\'comuna\'):\n                    manual[\'comuna\'] = comuna\n                else:\n                    manual.pop(\'comuna\', None)\n            registro[\'manual_campos\'] = manual\n\n            if montos is not None:\n                registro[\'montos\'] = {k: montos[k] for k in (\'neto\', \'iva\', \'total\')}\n                registro[\'estado\'] = \'manual\'\n                registro[\'motivo\'] = (\'Revisado manualmente: el total difiere de neto + IVA (pueden existir impuestos adicionales).\'\n                                      if abs(montos[\'neto\'] + montos[\'iva\'] - montos[\'total\']) > 2 else None)\n            registro[\'actualizado\'] = datetime.now(timezone.utc).isoformat()\n            datos[\'documentos\'][archivo] = registro\n            try:\n                _guardar_metadata(carpeta, datos)\n            except OSError:\n                LOG.exception(\'No se pudieron guardar datos manuales\')\n                return jsonify(error=\'No se pudieron guardar los datos.\'), 500\n        return jsonify(status=\'ok\')\n\n\ndef resumen_forzado(carpeta):\n    actualizar_carpeta(carpeta, forzar=True)\n    return resumen(carpeta)\n'
CSS_CONTENT = '        /* Montos V1.1.1: usa variables del tema; sin texto blanco fijo en modo claro. */\n        .btn-monto { padding-inline: 14px; font-weight: 800; }\n        .montos-total:last-child strong { font-size: clamp(1.6rem, 3vw, 2.7rem); color: var(--action-text); }\n        #modalMontos .modal-content { max-width: 1320px; }\n        .montos-summary { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 12px; padding: 20px 25px; }\n        .montos-total { padding: 14px 18px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface); color: var(--text-main); }\n        .montos-total strong { display: block; color: var(--text-main); font-size: clamp(1.15rem,2vw,1.75rem); font-variant-numeric: tabular-nums; }\n        .montos-total small { color: var(--text-muted); }\n        .montos-scroll { padding: 0 20px 16px; overflow: auto; }\n        .montos-table { min-width: 940px; font-variant-numeric: tabular-nums; color: var(--text-main); }\n        .montos-table thead { background: var(--bg-body); }\n        .montos-table th { position: sticky; top: 0; z-index: 2; color: var(--text-main); background: var(--bg-body); border-bottom-color: var(--border); }\n        .montos-table td { padding: 10px 12px; color: var(--text-main); }\n        .montos-table .col-numero { width: 72px; white-space: nowrap; }\n        .montos-table .col-emisor { min-width: 210px; }\n        .montos-table .col-comuna { min-width: 145px; }\n        .montos-table .col-ot { min-width: 170px; }\n        .montos-table .monto-num { text-align: right; white-space: nowrap; }\n        .montos-table.ocultar-ot .col-ot { display: none; }\n        #montosToggleOT[aria-pressed="false"] { opacity: .78; }\n        .montos-error { color: var(--status-warning-text); font-size: .8rem; display: block; }\n        .montos-actions { display: flex; flex-wrap: wrap; gap: 5px; }\n        #montosMensaje { color: var(--text-muted); padding: 4px 25px 14px; }\n        @media(max-width:650px) { .montos-summary { grid-template-columns: 1fr; } }\n'
JS_CONTENT = "        // Montos V1.1.1: emisor/comuna desde PDF, overrides manuales persistentes.\n        const dineroCLP = n => '$ ' + Number(n).toLocaleString('es-CL', {maximumFractionDigits:0});\n        let montosEnCarga = false;\n        const MONTOS_OT_KEY = 'sincronizador_montos_mostrar_ot';\n\n        function aplicarVisibilidadOT() {\n            const tabla = document.querySelector('#modalMontos .montos-table');\n            const boton = document.getElementById('montosToggleOT');\n            if (!tabla || !boton) return;\n            const mostrar = localStorage.getItem(MONTOS_OT_KEY) === '1';\n            tabla.classList.toggle('ocultar-ot', !mostrar);\n            boton.textContent = mostrar ? 'Ocultar OT' : 'Mostrar OT';\n            boton.setAttribute('aria-pressed', mostrar ? 'true' : 'false');\n        }\n\n        function toggleColumnaOT() {\n            const mostrarAhora = localStorage.getItem(MONTOS_OT_KEY) === '1';\n            localStorage.setItem(MONTOS_OT_KEY, mostrarAhora ? '0' : '1');\n            aplicarVisibilidadOT();\n        }\n\n        function cerrarModalMontos() { document.getElementById('modalMontos').style.display='none'; }\n        async function abrirModalMontos() {\n            if (!semanaSeleccionada) { alert('Selecciona una semana primero.'); return; }\n            document.getElementById('modalMontos').style.display='flex';\n            aplicarVisibilidadOT();\n            await cargarMontos();\n        }\n\n        async function cargarMontos() {\n            if (montosEnCarga || !semanaSeleccionada) return;\n            montosEnCarga=true;\n            const mensaje=document.getElementById('montosMensaje');\n            const semana=semanaSeleccionada;\n            mensaje.textContent='Leyendo facturas y metadata…';\n            try {\n                const r=await fetch('/api/montos?semana='+encodeURIComponent(semana));\n                const data=await r.json();\n                if (!r.ok) throw new Error(data.error || 'No se pudieron leer los montos');\n                if (semana !== semanaSeleccionada) return;\n                for (const k of ['neto','iva','total'])\n                    document.getElementById('montos'+k[0].toUpperCase()+k.slice(1)).textContent=dineroCLP(data.sumas[k]);\n\n                const tbody=document.getElementById('montosFilas');\n                const frag=document.createDocumentFragment();\n                for (const item of data.filas) {\n                    const tr=document.createElement('tr');\n                    const celda=(valor)=>{const td=document.createElement('td');td.textContent=(valor === null || valor === undefined || valor === '') ? '—' : valor;return td;};\n                    const n=item.montos;\n\n                    const numero=celda(item.numero || '—');\n                    numero.className='col-numero';\n                    numero.title=item.archivo || '';\n\n                    const emisor=celda(item.emisor || '—');\n                    emisor.className='col-emisor';\n                    const emisorDetalle=[];\n                    if (item.emisor_original) emisorDetalle.push('Emisor PDF: '+item.emisor_original);\n                    if (item.emisor_manual) emisorDetalle.push('Nombre mostrado corregido manualmente');\n                    emisor.title=emisorDetalle.join('\\n');\n\n                    const comuna=celda(item.comuna || '—');\n                    comuna.className='col-comuna';\n                    comuna.title=item.comuna_manual ? 'Comuna corregida manualmente' : (item.comuna_auto ? 'Comuna extraída del PDF' : 'Comuna no detectada');\n\n                    const ot=celda(item.ot || '—'); ot.className='col-ot';\n                    const neto=celda(n && item.estado !== 'duplicado' ? dineroCLP(n.neto) : '—'); neto.className='monto-num';\n                    const iva=celda(n && item.estado !== 'duplicado' ? dineroCLP(n.iva) : '—'); iva.className='monto-num';\n                    const total=celda(n && item.estado !== 'duplicado' ? dineroCLP(n.total) : '—'); total.className='monto-num';\n                    tr.append(numero, emisor, comuna, ot, neto, iva, total);\n\n                    const estado=document.createElement('td');\n                    const textos={manual:'Manual',extraido:'Extraído',manual_pendiente:'Pendiente',duplicado:'Duplicado'};\n                    const titulo=document.createElement('span'); titulo.textContent=textos[item.estado]||'Pendiente';\n                    estado.appendChild(titulo);\n                    if (item.motivo) {const info=document.createElement('small');info.className='montos-error';info.textContent=item.motivo;estado.appendChild(info);}\n                    const acciones=document.createElement('div');acciones.className='montos-actions';\n                    const editar=document.createElement('button');editar.type='button';editar.className='btn-ghost';editar.textContent='✎';editar.title='Corregir emisor, comuna o importes';\n                    editar.addEventListener('click',()=>editarMonto(item));acciones.appendChild(editar);\n                    const refrescar=document.createElement('button');refrescar.type='button';refrescar.className='btn-ghost';refrescar.textContent='↻';refrescar.title='Reanalizar los documentos de esta carpeta sin borrar correcciones manuales';\n                    refrescar.addEventListener('click',()=>refrescarCarpeta(item));acciones.appendChild(refrescar);\n                    estado.appendChild(acciones);tr.appendChild(estado);frag.appendChild(tr);\n                }\n                tbody.replaceChildren(frag);\n                if (!data.filas.length) {\n                    const fila=document.createElement('tr');const td=document.createElement('td');td.colSpan=8;td.textContent='No hay archivos cuyo nombre comience por F N° y sean PDF o imagen.';fila.appendChild(td);tbody.appendChild(fila);\n                }\n                mensaje.textContent=`${data.filas.length} documento(s). ${data.pendientes} pendiente(s) excluido(s) del total.`;\n                aplicarVisibilidadOT();\n            } catch(e) { mensaje.textContent='Error: '+e.message; }\n            finally {montosEnCarga=false;}\n        }\n\n        function pedirCLP(nombre, anterior) {\n            const v=prompt(nombre+' (pesos chilenos, sin decimales)', anterior==null?'':String(anterior));\n            if(v===null) return null;\n            const s=v.trim();\n            if (!/^(?:\\d{1,12}|\\d{1,3}(?:[.,]\\d{3})+)$/.test(s)) throw new Error('Importe no válido: '+nombre);\n            return Number(s.replace(/[.,]/g,''));\n        }\n\n        async function editarMonto(item) {\n            try {\n                const emisor=prompt('Emisor mostrado\\n(para una persona puedes dejar: primer nombre + primer apellido)', item.emisor || item.emisor_auto || '');\n                if(emisor===null) return;\n                const comuna=prompt('Comuna del emisor', item.comuna || item.comuna_auto || '');\n                if(comuna===null) return;\n\n                const payload={ruta:item.ruta,archivo:item.archivo,emisor:emisor.trim(),comuna:comuna.trim()};\n                const previo=item.montos||{};\n                const necesitaMontos=!item.montos;\n                const editarMontos=necesitaMontos || confirm('¿Quieres editar también Neto / IVA / Total?\\n\\nAceptar = editar montos\\nCancelar = conservar los montos actuales');\n                if (editarMontos) {\n                    const neto=pedirCLP('Neto',previo.neto); if(neto===null)return;\n                    const iva=pedirCLP('IVA',previo.iva); if(iva===null)return;\n                    const total=pedirCLP('Total',previo.total); if(total===null)return;\n                    if(Math.abs(neto+iva-total)>2 && !confirm('El total no coincide con Neto + IVA. ¿Hay impuestos adicionales y confirmas estos importes?')) return;\n                    payload.montos={neto,iva,total};\n                }\n\n                const r=await fetch('/api/montos/manual', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});\n                const data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo guardar');\n                await cargarMontos();\n            } catch(e) {alert(e.message);}\n        }\n\n        async function refrescarCarpeta(item) {\n            const b=document.getElementById('montosRefrescar');b.disabled=true;\n            try {\n                const r=await fetch('/api/montos/actualizar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ruta:item.ruta})});\n                const data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo actualizar');\n                await cargarMontos();\n            }catch(e){alert(e.message);}finally{b.disabled=false;}\n        }\n\n        async function refrescarTodosMontos() {\n            const btn=document.getElementById('montosRefrescar'); btn.disabled=true;\n            const mensaje=document.getElementById('montosMensaje'); mensaje.textContent='Reanalizando facturas PDF de la semana…';\n            try {\n                const r=await fetch('/api/montos/actualizar_semana',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({semana:semanaSeleccionada})});\n                const data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo actualizar');\n                await cargarMontos();\n            } catch(e) {mensaje.textContent='Error: '+e.message;}\n            finally {btn.disabled=false;}\n        }\n"


def abortar(msg, code=1):
    print("ERROR:", msg)
    sys.exit(code)


if not HTML.exists() or not MODULO.exists() or not SERVIDOR.exists():
    abortar("Ejecuta este instalador desde la carpeta SincronizadorWeb. Deben existir templates/index.html, factura_montos.py y servidor.py.")

servidor = SERVIDOR.read_text(encoding="utf-8")
if "registrar_rutas_montos" not in servidor:
    abortar("No encuentro la integración del módulo de montos en servidor.py. Este instalador corresponde al fix de V1.1.")

html = HTML.read_text(encoding="utf-8")
if 'id="modalMontos"' not in html or "Resumen de facturas" not in html:
    abortar("No encontré el bloque de Resumen de facturas esperado en index.html. No se modificó nada.")

marca = "Montos V1.1.1: emisor/comuna desde PDF"
if marca in html and "V1.1.1:" in MODULO.read_text(encoding="utf-8"):
    print("V1.1.1 ya está instalada. No se hicieron cambios.")
    sys.exit(0)

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup_dir = ROOT / f"backup_v1_1_1_{stamp}"
